import {bank,directions,directionName,questionsFor,analyzeExploration,simulateExploration,setDirection} from './engine.js';
import {language} from '../i18n.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const T=(en,zh,ms)=>({en,'zh-CN':zh,ms})[language]||en;
const L=value=>value[language]||value.en;
export const V2_STEPS=7;
export function translationNotice(){return language==='zh-CN'?'':`<div class="info-banner v2-language-notice" role="note"><p>${T('V2.0 questions and selected-answer quotations are available in the original Chinese only. English and Malay question translations are pending review. Navigation and report explanations stay in your selected language.','', 'Soalan V2.0 dan petikan jawapan hanya tersedia dalam bahasa Cina asal. Terjemahan soalan Inggeris dan Melayu menunggu semakan. Navigasi serta penjelasan laporan kekal dalam bahasa dipilih.')}</p></div>`;}
export function pageQuestions(profile,step){return step>0?questionsFor(profile.exploration.direction).slice((step-1)*2,step*2):[];}
export function collectExploration(form,profile){
 const data=new FormData(form);
 const direction=data.get('exploration-direction');if(direction&&direction!==profile.exploration.direction)setDirection(profile,String(direction));
 for(const q of bank.questions){if(form.querySelector(`[name="explore-${q.id}"]`)){
  const value=data.get('explore-'+q.id);if(value===null)delete profile.exploration.answers[q.id];else profile.exploration.answers[q.id]=String(value);
 }}
}
export function renderExplorationIntake(profile,step,errors={}){
 const isEntry=step===0,questions=isEntry?[]:pageQuestions(profile,step);
 const completed=profile.exploration.direction?questionsFor(profile.exploration.direction).filter(q=>profile.exploration.answers[q.id]).length:0;
 const questionCard=q=>`<fieldset class="field choice-field v2-question" data-question-id="${q.id}" lang="zh-CN" data-user-content><legend>${e(q.question)}</legend><div class="choice-grid">${q.options.map(option=>`<label class="choice ${profile.exploration.answers[q.id]===option.id?'is-selected':''}"><input type="radio" name="explore-${q.id}" value="${option.id}" ${profile.exploration.answers[q.id]===option.id?'checked':''}><span>${e(option.text)}</span></label>`).join('')}</div><details><summary>为什么问这个？</summary><p>${e(q.interpretation_note)}</p></details></fieldset>`;
 return `<main class="form-page"><div class="shell"><div class="back-row"><button type="button" class="text-button" data-action="${isEntry?'home':'prev'}">${isEntry?T('← Back to home','← 返回首页','← Kembali ke halaman utama'):T('← Previous step','← 上一步','← Langkah sebelumnya')}</button></div><div class="form-shell"><aside class="form-side"><span class="kicker">${T('CAREER EXPLORATION · V2.0','职业探索 · V2.0','PENEROKAAN KERJAYA · V2.0')}</span><h1>${T('Start with<br>your curiosity.','从你的<br>好奇心出发。','Mulakan dengan<br>rasa ingin tahu.')}</h1><p>${T('Explore your interests, experiences and approach to AI through everyday situations. There are no right answers to preference questions.','通过日常情境探索兴趣、经历与 AI 协作方式。偏好题没有标准答案。','Terokai minat, pengalaman dan pendekatan AI melalui situasi harian. Soalan keutamaan tiada jawapan betul.')}</p>${!isEntry?`<p>${e(directionName(profile.exploration.direction,language))}</p>`:''}</aside><div class="form-card"><div class="progress-top"><span>${isEntry?T('Choose one direction','选择一个方向','Pilih satu arah'):T('4 common + 8 direction questions','4 道通用题 + 8 道方向题','4 soalan umum + 8 soalan arah')}</span><span>${completed}/12</span></div><div class="progress-track"><div style="width:${isEntry?0:Math.round(step/6*100)}%"></div></div><h2>${isEntry?T('What would you like to explore?','你想先探索哪个方向？','Apakah yang ingin anda terokai?'):T('Consider the situation, then choose.','想一想情境，再做选择。','Pertimbangkan situasi, kemudian pilih.')}</h2>${translationNotice()}
 <form id="profile-form" novalidate>${isEntry?`<label for="exploration-direction">${T('Career direction','职业方向','Arah kerjaya')}</label><select id="exploration-direction" name="exploration-direction" aria-invalid="${!!errors.direction}" ${errors.direction?'aria-describedby="v2-direction-error"':''}><option value="">${T('Choose a direction','请选择方向','Pilih arah')}</option>${directions.map(d=>`<option value="${d.id}" ${profile.exploration.direction===d.id?'selected':''}>${e(directionName(d.id,language))}</option>`).join('')}</select>${errors.direction?`<p class="field-error" id="v2-direction-error" role="alert">${T('Choose one direction to load its 12 questions.','请选择一个方向以载入对应的 12 道题。','Pilih satu arah untuk memuatkan 12 soalannya.')}</p>`:''}<div class="info-banner"><p>${T('Competition demo: use fictional circumstances. Answers stay in this tab; no name, CV or upload is requested. AI sharing is optional and separate.','比赛演示请使用虚构情境。答案保留在本标签页，无需姓名、简历或上传；AI 分享为单独可选操作。','Demo pertandingan: gunakan keadaan rekaan. Jawapan kekal dalam tab ini; tiada nama, CV atau muat naik. Perkongsian AI ialah pilihan berasingan.')}</p></div>`:`<p class="field-help">${T('Choose one option for each situation. “Uncertain” and skipped answers are missing information, never zero potential. You may go back and change any answer.','每题选择一项。“不确定”或跳过均表示暂缺信息，不代表潜力为零；可随时返回修改。','Pilih satu pilihan bagi setiap situasi. “Tidak pasti” dan soalan dilangkau ialah maklumat tidak mencukupi, bukan potensi sifar. Anda boleh kembali mengubah jawapan.')}</p><div class="v2-original-questions" lang="zh-CN">${questions.map(questionCard).join('')}</div>`}
 <div class="form-actions"><span>${isEntry?T('One direction · 12 questions','一个方向 · 12 道题','Satu arah · 12 soalan'):`${(step-1)*2+1}–${step*2} / 12`}</span><button class="button primary" type="submit">${isEntry?T('Start with fictional circumstances →','使用虚构情境开始 →','Mula dengan keadaan rekaan →'):step===6?T('View exploration report →','查看探索报告 →','Lihat laporan penerokaan →'):T('Continue →','下一步 →','Teruskan →')}</button></div></form></div></div></div></main>`;
}
export function explorationNotice(){return `<div class="info-banner"><p>${T('V2.0 EXPLORATION · Local rules, no AI request. Interests, experience and AI strategies are separate. No suitability percentages or verified-skill claims.','V2.0 职业探索 · 本地规则，不调用 AI。兴趣、经历和 AI 策略分开解释；不计算适合度百分比，不声称已验证技能。','PENEROKAAN V2.0 · Peraturan tempatan, tiada permintaan AI. Minat, pengalaman dan strategi AI diasingkan. Tiada peratus kesesuaian atau dakwaan kemahiran disahkan.')}</p></div>`;}
function originalChoice(item){return `<blockquote class="v2-original-answer" lang="zh-CN" data-user-content>${e(item.text||'暂缺信息（尚未作答）')}</blockquote>`;}
function stageLabel(stage,max){return stage.score===null?T('Not enough information','暂缺信息','Maklumat tidak mencukupi'):`${stage.facet==='ai_judgement'?T('Scenario strategy level','情境策略级别','Tahap strategi senario'):T('Reported exposure stage','自述接触阶段','Tahap pendedahan dilaporkan')} ${stage.score} (0–${max})`;}
function selectionDetails(r){return `<details class="plan-mini"><summary>${T('Inspect all 12 selections and rules','查看 12 项选择与规则','Semak 12 pilihan dan peraturan')}</summary>${r.exploration.selected.map(item=>`<section class="v2-answer-row"><strong>${item.questionId}</strong><p lang="zh-CN" data-user-content>${e(item.question)}</p>${originalChoice(item)}<small>${item.tag&&item.tag!=='unknown'?e(item.tag):item.score===null?T('Unknown · excluded from stages','未知 · 不计入阶段','Tidak diketahui · dikecualikan daripada tahap'):`${item.score}/${item.facet==='ai_judgement'?3:4}`}</small><p lang="zh-CN" data-user-content>${e(item.note)}</p></section>`).join('')}</details>`;}
function stageAdvice(kind,stage){
 if(stage.score===null)return T('Try a small example first. Missing information does not justify a negative conclusion.','先观察一个小示例；缺失信息不构成负面结论。','Cuba contoh kecil dahulu. Maklumat tidak mencukupi tidak menyokong kesimpulan negatif.');
 if(kind==='experience')return stage.score<=1?T('Begin with a guided example and keep one work sample. No prior experience is required.','从有指导的示例开始，保留一个工作样本；不要求已有经验。','Mulakan dengan contoh berpandu dan simpan satu sampel kerja. Pengalaman terdahulu tidak diperlukan.'):T('Build on the experience you reported: change one condition and record what worked, what failed and what you revised.','基于你自述的经历，改变一个条件并记录有效做法、错误和修正。','Bina berdasarkan pengalaman dilaporkan: ubah satu keadaan dan catat perkara berkesan, kegagalan serta pembetulan.');
 if(kind==='verification')return stage.score<2?T('Before adopting an AI output, compare its important claims with a reliable independent source or a concrete test. Asking the same AI again is not independent verification.','采用 AI 输出前，用可靠独立来源或具体测试核查重要说法；再次询问同一个 AI 不等于独立验证。','Sebelum menerima output AI, banding dakwaan penting dengan sumber bebas dipercayai atau ujian konkrit. Bertanya AI yang sama semula bukan pengesahan bebas.'):T('Keep the check you selected, and record its limits. A hypothetical response still needs evidence from an actual task.','保留你选择的核查步骤，并记录局限；情境选择仍需实际任务证据验证。','Kekalkan semakan dipilih dan catat batasannya. Jawapan hipotesis masih memerlukan bukti daripada tugas sebenar.');
 return stage.score<=1?T('You can complete the exercise manually. If you try AI, start with one small step and compare the output with your own work.','可以先手动完成练习；若尝试 AI，从一个小步骤开始，与自己完成的结果比较。','Anda boleh melakukan latihan secara manual. Jika mencuba AI, mulakan satu langkah kecil dan banding dengan kerja sendiri.'):T('Document where AI helped, independently check a key result, and retain human responsibility for the final output.','记录 AI 参与的环节，独立核查一项关键结果，最终产出由人负责。','Dokumenkan bantuan AI, semak satu hasil utama secara bebas dan kekalkan tanggungjawab manusia bagi output akhir.');
}
export function renderExplorationSimulator(r,choices={}){
 const next=simulateExploration(r.exploration,choices),base=simulateExploration(r.exploration);
 const experienceQuestion=questionsFor(r.exploration.direction).find(q=>q.facet==='experience');
 return `<section class="whatif" data-v2-simulator><div class="sim-heading"><h2>${T('What If · explore a different plan','What If · 探索另一种计划','What If · terokai pelan berbeza')}</h2><button class="text-button" data-action="v2-reset">${T('Reset assumptions','重置假设','Tetapkan semula andaian')}</button></div><p>${T('Only planning assumptions change. More time does not create skills, experience or career suitability. Your original answers stay unchanged.','这里仅改变规划假设。更多学习时间不会自动产生技能、经历或职业适合度；原始回答保持不变。','Hanya andaian perancangan berubah. Masa tambahan tidak mewujudkan kemahiran, pengalaman atau kesesuaian kerjaya. Jawapan asal kekal.')}</p><div class="sim-controls"><label for="v2-hours">${T('Assume weekly practice hours','假设每周实践小时数','Andaikan jam latihan seminggu')}<output>${next.weeklyHours}h</output><input id="v2-hours" type="range" min="0.5" max="20" step="0.5" value="${next.weeklyHours}" data-v2-control="hours"></label><label for="v2-experience">${T('Assume an experience stage (not earned)','假设经历阶段（不代表已获得）','Andaikan tahap pengalaman (belum diperoleh)')}<select id="v2-experience" data-v2-control="experience"><option value="baseline">${T('Keep reported stage','保持原自述','Kekalkan tahap dilaporkan')}</option>${experienceQuestion.options.map(option=>`<option value="${option.id}" lang="zh-CN" ${choices.experience===option.id?'selected':''}>${e(option.text)}</option>`).join('')}</select></label></div>${language!=='zh-CN'?`<p class="field-help">${T('Experience choices above are the original Chinese bank text; translations are pending.','','Pilihan pengalaman di atas ialah teks Cina asal; terjemahan menunggu semakan.')}</p>`:''}<div class="sim-comparison" aria-live="polite"><article><span>${T('Reported experience → assumed','自述经历 → 假设经历','Pengalaman dilaporkan → andaian')}</span><strong>${base.experience??'—'} → ${next.experience??'—'}</strong><small>${T('Exposure stage only · 0–4; unknown stays unknown','仅为经历阶段 · 0–4；未知仍为未知','Tahap pendedahan sahaja · 0–4; tidak diketahui kekal begitu')}</small></article><article><span>${T('Illustrative task effort','示例任务工时','Usaha tugas contoh')}</span><strong>${base.effortHours}h → ${next.effortHours}h</strong><small>${T('Editorial sizing changes with the assumed exercise scaffold, not a skills score','估时随假设的练习支架变化，并非技能分数','Anggaran editorial berubah mengikut sokongan latihan andaian, bukan skor kemahiran')}</small></article><article><span>${T('Schedule length','排期长度','Tempoh jadual')}</span><strong>${base.weeks} → ${next.weeks}</strong><small>${T('weeks · a planning estimate, not a readiness forecast','周 · 规划估计，不是就业准备预测','minggu · anggaran perancangan, bukan ramalan kesiapsiagaan')}</small></article></div><p>${T('Next practice format','下一步练习方式','Bentuk latihan seterusnya')}: ${next.scaffold==='guided'?T('Follow a worked example','跟随示例尝试','Ikuti contoh berpandu'):next.scaffold==='adapt'?T('Adapt one template step','调整模板的一步','Ubah satu langkah templat'):next.scaffold==='independent'?T('Make and review an independent sample','独立完成样本并复核','Hasilkan dan semak sampel sendiri'):T('Observe an example before deciding','先观察示例再决定','Perhatikan contoh sebelum membuat keputusan')}</p>${next.budgetIsAssumed?`<p>${T('No time budget was supplied; 1 hour/week is an illustrative assumption you can change.','未提供时间预算，暂用每周 1 小时作排期示例，可自行修改。','Bajet masa tidak diberikan; 1 jam/minggu ialah andaian contoh yang boleh diubah.')}</p>`:''}<p>${T('AI use and verification stages do not change in this simulation. An assumed project stage is not an observed achievement.','本模拟不改变 AI 使用及核查阶段；假设的项目经历不代表已经完成的成果。','Tahap penggunaan dan pengesahan AI tidak berubah dalam simulasi. Tahap projek andaian bukan pencapaian diperhatikan.')}</p></section>`;
}
export function renderExplorationSection(r,page,path='A',choices={}){
 const x=r.exploration,s=x.stages,selected=r.analysis.paths.find(p=>p.kind===path)||r.analysis.paths[0];
 const heads={capability:T('Your exploration, explained','你的探索线索','Penerokaan anda diterangkan'),impact:T('How you approach AI at work','你如何在任务中使用 AI','Pendekatan anda terhadap AI dalam tugas'),paths:T('Two experiments in your selected direction','在所选方向尝试两条路线','Dua eksperimen dalam arah dipilih'),plan:T('A small task to try this week','本周可尝试的小任务','Tugas kecil untuk dicuba minggu ini')};
 const card=(title,content)=>`<article class="plan-mini"><h3>${title}</h3>${content}</article>`;
 const preference=item=>originalChoice(item)+(item.unknown?`<p>${T('Keep exploring; uncertainty is not a poor match.','可以继续探索；不确定不等于不匹配。','Teruskan meneroka; ketidakpastian bukan padanan lemah.')}</p>`:'');
 const stage=(label,item,max,kind)=>card(label,`<strong>${stageLabel(item,max)}</strong>${originalChoice(item)}<p>${stageAdvice(kind,item)}</p>`);
 let body='';
 if(page==='capability')body=`<div class="profile-summary"><p>${e(r.analysis.summary.text)}</p><p>${x.evidence.known}/12 · ${T('informative choices; uncertainty is excluded','项有信息的选择；未知项排除','pilihan bermaklumat; ketidakpastian dikecualikan')}</p>${x.evidence.keyMissing.length?`<p>${T('Important evidence is incomplete','关键资料暂缺','Bukti penting tidak lengkap')}: ${x.evidence.keyMissing.join(' · ')}</p>`:''}</div><div class="hero-buttons"><button class="button secondary" data-action="page:paths">${T('Try What If','进入 What If 模拟','Cuba What If')}</button><button class="text-button" data-action="page:plan">${T('See this week’s practice','查看本周实践','Lihat latihan minggu ini')}</button></div><div class="local-dimensions">${card(T('Interests and task preferences','兴趣与任务偏好','Minat dan keutamaan tugas'),preference(x.preferences.interest)+preference(x.preferences.subdomain)+preference(x.preferences.task))}${stage(T('Relevant experience','相关经历','Pengalaman berkaitan'),s.experience,4,'experience')}${stage(T('General AI exposure','通用 AI 接触经历','Pendedahan AI umum'),s.generalAI,4,'ai')}${stage(T('AI in this direction','本方向 AI 使用经历','Penggunaan AI dalam arah ini'),s.domainAI,4,'ai')}${stage(T('AI verification strategy','AI 输出核查策略','Strategi pengesahan AI'),s.verification,3,'verification')}${card(T('Growth and next practice','成长空间与下一步','Perkembangan dan latihan seterusnya'),preference(x.preferences.problemStyle)+preference(x.preferences.growth)+`<p>${e(selected.next_step.text)}</p>`)}</div>${selectionDetails(r)}`;
 if(page==='impact')body=`<div class="task-grid">${stage(T('General AI use','通用 AI 使用','Penggunaan AI umum'),s.generalAI,4,'ai')}${stage(T('AI use for this direction','方向任务中的 AI 使用','Penggunaan AI dalam tugas arah ini'),s.domainAI,4,'ai')}${stage(T('Verification and error awareness','核查与错误意识','Pengesahan dan kesedaran ralat'),s.verification,3,'verification')}</div><section class="plan-mini"><h2>${T('Learning through change','通过实践理解变化','Belajar melalui perubahan')}</h2>${preference(x.preferences.growth)}<p>${T('A chosen challenge is a preference, not proof of willingness or resistance to AI. Try one optional AI-assisted step and compare it with a manual result before deciding.','所选挑战是偏好，不证明愿意或抵触 AI。可以自愿尝试一个 AI 辅助步骤，与手动结果比较后再决定。','Cabaran dipilih ialah keutamaan, bukan bukti kesediaan atau penolakan AI. Cuba satu langkah bantuan AI secara pilihan dan banding dengan hasil manual sebelum membuat keputusan.')}</p><p>${e(r.analysis.tasks[0].human_check.text)}</p></section>`;
 if(page==='paths')body=`<div class="paths-grid">${r.analysis.paths.map(p=>`<article class="path-card ${p.kind===path?'selected':''}"><span class="kicker">${T('Path','路线','Laluan')} ${p.kind}</span><h2>${e(r.ranking.find(role=>role.id===p.role_id).title)}</h2><p>${e(p.why.text)}</p>${preference(p.focus)}<p>${e(p.next_step.text)}</p><p>${e(p.challenge.text)}</p><button class="button secondary" data-action="select:${p.kind}">${p.kind===path?T('Selected','已选择','Dipilih'):T('Try this route','尝试这条路线','Cuba laluan ini')}</button></article>`).join('')}</div><p>${T('Both routes belong to the direction you answered. Other directions have not been assessed or ranked.','两条路线均属于你回答的方向；其他方向尚未测评，不作排名。','Kedua-dua laluan dalam arah yang dijawab. Arah lain belum dinilai atau diberi kedudukan.')}</p>${renderExplorationSimulator(r,choices)}`;
 if(page==='plan')body=`<div class="plan-summary"><div><span>${T('EDITORIAL EXERCISE · NOT A QUALIFICATION','团队设计的体验任务 · 非职业资格','LATIHAN EDITORIAL · BUKAN KELAYAKAN')}</span><h2>${e(L(r.project.title))}</h2><p>${e(L(r.project.task))}</p></div><div class="time-token"><strong>${r.simulation.weeklyHours}h</strong><span>${T('illustrative weekly plan','示例每周排期','pelan mingguan contoh')}</span></div></div><section class="plan-mini"><h3>${T('Your exploration goal','你的探索目标','Matlamat penerokaan anda')}</h3>${preference(x.preferences.goal)}<p>${e(r.goalAdvice)}</p></section><section class="plan-mini"><h3>${T('Focus from your choice','按你的选择聚焦','Fokus daripada pilihan anda')}</h3>${preference(selected.focus)}</section><p>${T('First week: try a small portion within your budget. The full exercise may continue later; estimated effort is not an entry requirement.','第一周先在时间预算内尝试一小部分；完整练习可后续继续，估算工时不是职业准入要求。','Minggu pertama: cuba bahagian kecil dalam bajet masa. Latihan penuh boleh diteruskan kemudian; anggaran usaha bukan syarat kelayakan.')}</p><div class="week-list">${selected.weeks.map((w,i)=>`<article class="plan-mini"><span class="kicker">${T('Practice step','实践步骤','Langkah latihan')} ${i+1}</span><p>${e(w.action.text)}</p><p><strong>${T('Deliverable','交付物','Hasil kerja')}:</strong> ${e(w.deliverable)}</p><p><strong>${T('Check','核查','Semakan')}:</strong> ${e(w.validation)}</p><a href="${e(r.evidence.sources[w.resource_id].url)}" target="_blank" rel="noopener noreferrer">${e(r.evidence.sources[w.resource_id].title)}</a></article>`).join('')}</div>${renderExplorationSimulator(r,choices)}`;
 return explorationNotice()+translationNotice()+`<section class="explorer-page v2-results"><div class="report-head"><span class="kicker">V2.0 · ${e(directionName(x.direction,language))}</span><h1>${heads[page]}</h1><p>${T('Interests, experience, AI exposure and verification are interpreted separately.','兴趣、经历、AI 接触及核查策略分别解释。','Minat, pengalaman, pendedahan AI dan pengesahan ditafsir secara berasingan.')}</p></div>${body}</section>`;
}
